<template>
  <div class="commisRecord">
    <title-line :title="title" />
    <div class="commisRecord-content">
      <div class="filter">
        <div class="filter-box" @click="showPop=!showPop">
          <div class="text">{{ typeList.find(item=>item.value===currentData).name }}</div>
          <div class="drow_icon">
            <van-icon name="arrow-down" />
          </div>
        </div>
        <div v-if="showPop" class="typePop">
          <div v-for="item in typeList" :key="item.value" class="filterBox" @click="currentData=item.value;showPop=false;onRefresh()">
            <div class="text">{{ item.name }}</div>
          </div>
        </div>
      </div>
      <!-- <div class="filterType">
        <div class="filterLeft">
          <div class="content" @click="showFilter=true">
            <div class="text">{{ currentData==='1'?$t('wdsr.wdsr44'):$t('wdsr.wdsr45') }}</div>
            <div class="drow-icon" />
          </div>
          <div v-if="showFilter" class="typePop">
            <div class="filterBox" @click="currentData='1';showFilter=false;onRefresh()">
              <div class="text">{{ $t('wdsr.wdsr44') }}</div>
            </div>
            <div class="filterBox" @click="currentData='2';showFilter=false;onRefresh()">
              <div class="text">{{ $t('wdsr.wdsr45') }}</div>
            </div>
          </div>
        </div>
      </div> -->

      <div class="recordBox">
        <div class="thead">
          <span>{{ $t('wdsr.wdsr46') }}</span>
          <!-- <span>输赢</span> -->
          <span>{{ $t('wdsr.wdsr47') }}</span>
          <!-- <span>团队人数</span> -->
          <span>{{ $t('wdsr.wdsr48') }}</span>
        </div>
        <div class="tbody">
          <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
            <van-list
              v-model="loading"
              :finished="finished"
              :loading-text="$t('tzjl.tzjl50')"
              finished-text=""
              @load="onLoad"
            >
              <is-empty v-if="recordList.length===0" />
              <div v-for="(item,index) in recordList" :key="index" class="list">
                <span>{{ item.uname }}</span>
                <!-- <span :class="Number(item.winmons)>0?'yellow':(Number(item.winmons)<0?'red':'white')">{{ item.winmons }}</span> -->
                <span :class="Number(item.mons)>0?'yellow':(Number(item.mons)<0?'red':'white')">{{ item.mons }}</span>
                <!-- <span>{{ item.teamnums }}</span> -->
                <!-- <span>{{ item.uaname }}</span> -->
                <span>
                  <div v-if="item.uaname.length>1" class="icon" @click="open(item.uaurl)" />
                  <div v-else class="icon1" />
                </span>

              </div>
            </van-list>
          </van-pull-refresh>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { agentQuery } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: String,
      default: '哈希一分大小'
    }
  },
  data() {
    return {
      title: this.$t('wdsr.wdsr02'),
      showPop: false,
      currentData: '1',
      recordList: [
      ],
      typeList: [{ name: this.$t('wdsr.wdsr44'), value: '1' }, { name: this.$t('wdsr.wdsr45'), value: '2' }],
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10
    }
  },
  created() {
    this.currentData = this.$route.query.type
  },
  methods: {
    open(url) {
      window.open(url)
    },
    // goMore() {
    //   this.$router.push({ path: '/rechargeRecord' })
    // }
    async onLoad() { //, ucode: this.$store.getters.userInfo.ucode
      const res = await agentQuery({ pages: this.pageNum, gametype: this.$route.query.gametype, type: this.currentData })
      if (this.refreshing) {
        this.recordList = []
        this.refreshing = false
      }
      this.recordList = this.recordList.concat(res.datalist)
      this.loading = false
      this.pageNum++
      if (this.recordList.length >= Number(res.totalrow)) {
        this.finished = true
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    }
  }

}
</script>
